using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B2Access {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");string h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B2_Cooling/"));var origin=new Vector3(19,-34,-1);var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();bool enabled=cc.enabled;cc.enabled=false;Physics.SyncTransforms();var rows=new List<object>();int tested=0;try{foreach(float floor in new[]{0f,3.6f}){var free=new HashSet<Vector2Int>();float cell=.30f;int n=37;for(int x=-n;x<=n;x++)for(int z=-n;z<=n;z++){var p=origin+new Vector3(x*cell,floor,z*cell);tested++;if(!Physics.Raycast(p+Vector3.up*.25f,Vector3.down,out var hit,.45f,~0,QueryTriggerInteraction.Ignore)||Mathf.Abs(hit.point.y-p.y)>.06f)continue;if(Physics.OverlapCapsule(p+Vector3.up*.45f,p+Vector3.up*1.45f,.34f,~0,QueryTriggerInteraction.Ignore).Length==0)free.Add(new Vector2Int(x,z));}Vector2Int closest(Vector3 p)=>free.OrderBy(q=>Vector2.Distance(new Vector2(q.x*cell,q.y*cell),new Vector2(p.x,p.z))).First();var start=closest(floor==0?Vector3.zero:new Vector3(-6.2f,0,2));var seen=new HashSet<Vector2Int>{start};var queue=new Queue<Vector2Int>();queue.Enqueue(start);while(queue.Count>0){var p=queue.Dequeue();foreach(var d in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right}){var q=p+d;if(free.Contains(q)&&seen.Add(q))queue.Enqueue(q);}}var targets=new Dictionary<string,Vector3>();if(floor==0){foreach(var d in JArray.Parse(File.ReadAllText(h+"doors.json"))){float a=(float)d["angle"]*Mathf.Deg2Rad;targets["portal_"+(string)d["id"]]=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*9.3f;}targets["bench"]=new Vector3(-7.8f,0,2.65f);targets["control"]=new Vector3(3.05f,0,6.6f);targets["exchanger"]=new Vector3(0,0,6);targets["HVAC"]=new Vector3(7.3f,0,-.5f);targets["west_stair"]=new Vector3(-6.2f,0,-7.9f);targets["east_stair"]=new Vector3(6.2f,0,-7.9f);}else{targets["west_valves"]=new Vector3(-5.8f,0,3.25f);targets["east_valves"]=new Vector3(5.8f,0,3.25f);targets["crosswalk"]=new Vector3(0,0,4.5f);targets["east_landing"]=new Vector3(6.2f,0,-1.7f);}foreach(var t in targets){var p=closest(t.Value);float error=Vector2.Distance(new Vector2(p.x*cell,p.y*cell),new Vector2(t.Value.x,t.Value.z));rows.Add(new{floor,target=t.Key,reachable=seen.Contains(p)&&error<.65f,offset=error});}}}finally{cc.enabled=enabled;Physics.SyncTransforms();}var result=new{samples=tested,radius=.34f,height=1.79f,targets=rows};File.WriteAllText(Path.GetFullPath(Path.Combine(h,"../../Docs/Review/2026-11-09_B2_Cooling/access.json")),JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
